function validate([nums, modulo, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is an integer from 1 to 10^9.';
  if (!Number.isInteger(modulo) || modulo < 1 || modulo > 1000000000) return 'modulo is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 0 || k >= modulo) return 'k must satisfy 0 <= k < modulo.';
  return null;
}

