function countInterestingSubarrays(nums, modulo, k) {
  const seen = new Map();
  seen.set(0, 1);
  let prefix = 0;
  let count = 0;

  for (const value of nums) {
    if (value % modulo === k) {
      prefix = (prefix + 1) % modulo;
    }
    const need = (prefix - k + modulo) % modulo;
    count += seen.get(need) ?? 0;
    seen.set(prefix, (seen.get(prefix) ?? 0) + 1);
  }
  return count;
}

