function countInterestingSubarrays(nums, modulo, k) {
  let total = 0;
  for (let l = 0; l < nums.length; l++) {
    let cnt = 0;
    for (let r = l; r < nums.length; r++) {
      if (nums[r] % modulo === k) cnt++;
      if (cnt % modulo === k) total++;
    }
  }
  return total;
}

