function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const top = large ? 1000000000 : 12;
  const shape = Math.floor(rand() * 3);
  let modulo;
  if (!large) modulo = 1 + Math.floor(rand() * 4);
  else if (shape === 0) modulo = 1 + Math.floor(rand() * 5);
  else if (shape === 1) modulo = 2 + Math.floor(rand() * 49);
  else modulo = 1 + Math.floor(rand() * top);
  const k = Math.floor(rand() * Math.min(modulo, large && shape === 2 ? 3 : modulo));
  // A hit is k plus a multiple of modulo, kept between 1 and top.
  const lowest = k === 0 ? 1 : 0;
  const highest = Math.floor((top - k) / modulo);
  const hit = () => k + modulo * (lowest + Math.floor(rand() * (highest - lowest + 1)));
  const chance = rand();
  const nums = Array.from({ length: n }, () => (rand() < chance ? hit() : 1 + Math.floor(rand() * top)));
  return [nums, modulo, k];
}
